import itertools
import json

def solve_puzzle():
    houses = [1,2,3,4,5,6]
    names = ['Arnold','Peter','Carol','Alice','Bob','Eric']
    children = ['Alice','Timothy','Bella','Meredith','Fred','Samantha']
    smoothies = ['desert','cherry','watermelon','blueberry','lime','dragonfruit']

    solutions = []

    for name_perm in itertools.permutations(names):
        # Name constraints
        # 3. Alice is not in the fifth house.
        if name_perm[4] == 'Alice':
            continue
        # 9. Arnold is not in the second house.
        if name_perm[1] == 'Arnold':
            continue
        # 11. Arnold is directly left of Carol.
        try:
            idx_arnold = name_perm.index('Arnold')
            idx_carol = name_perm.index('Carol')
        except ValueError:
            continue
        if idx_arnold + 1 != idx_carol:
            continue

        pos_name = {name_perm[i]: i for i in range(6)}  # 0-based positions

        for child_perm in itertools.permutations(children):
            # Child constraints
            # 13. The person's child is named Meredith is in the sixth house.
            if child_perm[5] != 'Meredith':
                continue
            # 4. The person's child is named Samantha is not in the second house.
            if child_perm[1] == 'Samantha':
                continue
            pos_child = {child_perm[i]: i for i in range(6)}

            # 6. Alice is the person's child is named Alice.
            if pos_child['Alice'] != pos_name['Alice']:
                continue
            # 10. Bob is the person who is the mother of Timothy.
            if pos_child['Timothy'] != pos_name['Bob']:
                continue
            # 8. Peter is somewhere to the right of the person's child is named Samantha.
            if pos_name['Peter'] <= pos_child['Samantha']:
                continue

            for smoothie_perm in itertools.permutations(smoothies):
                # Smoothie constraints
                # 14. The Dragonfruit smoothie lover is the person's child is named Meredith.
                if smoothie_perm[5] != 'dragonfruit':
                    continue
                pos_smoothie = {smoothie_perm[i]: i for i in range(6)}

                # 7. Alice is the Watermelon smoothie lover.
                if pos_smoothie['watermelon'] != pos_name['Alice']:
                    continue
                # 12. The person who likes Cherry smoothies is directly left of the person's child is named Samantha.
                if pos_smoothie['cherry'] + 1 != pos_child['Samantha']:
                    continue
                # 5. The Watermelon smoothie lover is somewhere to the right of the person who likes Cherry smoothies.
                if pos_smoothie['watermelon'] <= pos_smoothie['cherry']:
                    continue
                # 2. The person who drinks Blueberry smoothies is somewhere to the left of the person's child is named Fred.
                if pos_smoothie['blueberry'] >= pos_child['Fred']:
                    continue
                # 1. The person's child is named Fred and the Desert smoothie lover are next to each other.
                if abs(pos_child['Fred'] - pos_smoothie['desert']) != 1:
                    continue

                # All constraints satisfied; construct solution
                solution_rows = []
                for i in range(6):
                    house_num = str(i+1)
                    name_at_house = name_perm[i]
                    child_at_house = child_perm[i]
                    smoothie_at_house = smoothie_perm[i]
                    solution_rows.append([house_num, name_at_house, child_at_house, smoothie_at_house])

                solutions.append({
                    "solution": {
                        "header": ["House", "Name", "Children", "Smoothie"],
                        "rows": solution_rows
                    }
                })
                # If unique solution is expected, we can break after first
                # But continue to ensure computation is not hardcoded
                # We'll return the first solution found
                return solutions[0]

    # If no solution found, return empty structure (should not happen with valid puzzle)
    return {
        "solution": {
            "header": ["House", "Name", "Children", "Smoothie"],
            "rows": []
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
